def diag(grid):
 from collections import Counter
 h,w=len(grid),len(grid[0]); bg=Counter(sum(grid,[])).most_common(1)[0][0]
 seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==bg or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    y,x=q.pop();co.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and (yy,xx) not in seen:seen.add((yy,xx));q.append((yy,xx))
   comps.append(co)
 return bg,sorted([(len(co), Counter(grid[r][c] for r,c in co), (min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co))) for co in comps],reverse=True)
